/**
 * @suppress
 */
public object FfiConverterTypeSurface: FfiConverter<Surface, Long> {
    override fun lower(value: Surface): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): Surface {
        return Surface(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): Surface {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: Surface) = 8UL

    override fun write(value: Surface, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



