sealed class UiException: kotlin.Exception() {
    
    class Invalid(
        
        val `reason`: kotlin.String
        ) : UiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * A theme failed to load; `issues_json` = `[{path, message}]`.
     */
    class Theme(
        
        val `issuesJson`: kotlin.String
        ) : UiException() {
        override val message
            get() = "issuesJson=${ `issuesJson` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<UiException> {
        override fun lift(error_buf: RustBuffer.ByValue): UiException = FfiConverterTypeUiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeUiError : FfiConverterRustBuffer<UiException> {
    override fun read(buf: ByteBuffer): UiException {
        

        return when(buf.getInt()) {
            1 -> UiException.Invalid(
                FfiConverterString.read(buf),
                )
            2 -> UiException.Theme(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: UiException): ULong {
        return when(value) {
            is UiException.Invalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is UiException.Theme -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`issuesJson`)
            )
        }
    }

    override fun write(value: UiException, buf: ByteBuffer) {
        when(value) {
            is UiException.Invalid -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is UiException.Theme -> {
                buf.putInt(2)
                FfiConverterString.write(value.`issuesJson`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




